Translate the following GNU C++0x code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++0x code you have to translate:
<original_code>
#include <iostream>
#include <cmath>
#include <algorithm>
using namespace std;

long long x, y, n;

long long gcd(long long a, long long b) {
    while (b != 0) {
        long long temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

int main() {
    cin >> x >> y >> n;
    long long a, b;

    if (n >= y) {
        long long m = gcd(x, y);
        a = x / m;
        b = y / m;
    } else {
        double min_diff = 1e15;
        for (int i = 1; i <= n; ++i) {
            double ratio = (double)x / y;
            double aa_floor = floor((double)x * i / y);
            if (abs(aa_floor / i - ratio) < min_diff) {
                a = aa_floor;
                b = i;
                min_diff = abs(aa_floor / i - ratio);
            }
            double aa_ceil = ceil((double)x * i / y);
            if (abs(aa_ceil / i - ratio) < min_diff) {
                a = aa_ceil;
                b = i;
                min_diff = abs(aa_ceil / i - ratio);
            }
        }
    }
    cout << a << "/" << b << endl;
    return 0;
}
